trait Iterable<A> {
    fn iterate(&self, blk: impl FnMut(&A) -> bool);
}

impl<A> Iterable<A> for &[A] {
    fn iterate(&self, mut f: impl FnMut(&A) -> bool) {
        for e in self.iter() {
            if !f(e) { break; }
        }
    }
}

fn length<A, T>(x: T) -> usize
where
    T: Iterable<A>,
{
    let mut len = 0;
    x.iterate(|_| { len += 1; true });
    return len;
}

